import{_ as p,a0 as l,w as o,s as r,ao as d,I as t,x as a,a1 as e,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"為什麼應該在 Linux 上使用命名管道 | LCTT x X-CMD","titleTemplate":false,"description":"為什麼應該在 Linux 上使用命名管道 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"為什麼應該在 Linux 上使用命名管道 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"為什麼應該在 Linux 上使用命名管道 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20180131 Why you should use named pipes on Linux","title":"為什麼應該在 Linux 上使用命名管道","tag":"201802","desc":""},"relativePath":"201802/20180131 Why you should use named pipes on Linux.md","filePath":"[post].md"}'),h={name:"201802/20180131 Why you should use named pipes on Linux.md"};function u(g,s,c,k,b,m){const i=l("Link");return o(),r("div",null,[s[13]||(s[13]=d(`<h1 id="為什麼應該在-linux-上使用命名管道" tabindex="-1">為什麼應該在 Linux 上使用命名管道 <a class="header-anchor" href="#為什麼應該在-linux-上使用命名管道" aria-label="Permalink to “為什麼應該在 Linux 上使用命名管道”">​</a></h1><blockquote><p>命名管道並不常用，但是它們為進程間通訊提供了一些有趣的特性。</p></blockquote><p><img src="https://images.techhive.com/images/article/2017/05/blue-1845806_1280-100722976-large.jpg" alt=""></p><p>估計每一位 Linux 使用者都熟悉使用 “|” 符號將數據從一個進程傳輸到另一個進程的操作。它使用户能簡便地從一個命令輸出數據到另一個命令，並篩選出想要的數據而無須寫腳本進行選擇、重新格式化等操作。</p><p>還有另一種管道， 雖然也叫“管道”這個名字卻有着非常不同的性質。即您可能尚未使用甚至尚未知曉的——命名管道。</p><p>普通管道與命名管道的一個主要區別就是命名管道是以文件形式實實在在地存在於文件系統中的，沒錯，它們表現出來就是文件。但是與其它文件不同的是，命名管道文件似乎從來沒有文件內容。即使用户往命名管道中寫入大量數據，該文件看起來還是空的。</p><h3 id="如何在-linux-上創建命名管道" tabindex="-1">如何在 Linux 上創建命名管道 <a class="header-anchor" href="#如何在-linux-上創建命名管道" aria-label="Permalink to “如何在 Linux 上創建命名管道”">​</a></h3><p>在我們研究這些空空如也的命名管道之前，先追根溯源來看看命名管道是如何被創建的。您應該使用名為 <code>mkfifo</code> 的命令來創建它們。為什麼提及“FIFO”？是因為命名管道也被認為是一種 FIFO 特殊文件。術語 “FIFO” 指的是它的<ruby>先進先出<rt>first-in, first-out</rt></ruby>特性。如果你將冰淇淋盛放到碟子中，然後可以品嚐它，那麼你執行的就是一個LIFO（<ruby>後進先出<rt>last-in, first-out</rt></ruby>操作。如果你通過吸管喝奶昔，那你就在執行一個 FIFO 操作。好，接下來是一個創建命名管道的例子。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkfifo mypipe</span></span>
<span class="line"><span>$ ls -l mypipe</span></span>
<span class="line"><span>prw-r-----. 1 shs staff 0 Jan 31 13:59 mypipe</span></span></code></pre></div><p>注意一下特殊的文件類型標記 “p” 以及該文件大小為 0。您可以將重定向數據寫入命名管道文件，而文件大小依然為 0。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;Can you read this?&quot; &gt; mypipe</span></span></code></pre></div><p>正如上面所説，敲擊回車後似乎什麼都沒有發生（LCTT 譯註：沒有返回命令列提示符）。</p><p>另外再開一個終端，查看該命名管道的大小，依舊是 0：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l mypipe</span></span>
<span class="line"><span>prw-r-----. 1 shs staff 0 Jan 31 13:59 mypipe</span></span></code></pre></div><p>也許這有違直覺，用户輸入的文本已經進入該命名管道，而你仍然卡在輸入端。你或者其他人應該等在輸出端，並準備讀取放入管道的數據。現在讓我們讀取看看。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat mypipe</span></span>
<span class="line"><span>Can you read this?</span></span></code></pre></div><p>一旦被讀取之後，管道中的內容就沒有了。</p><p>另一種研究命名管道如何工作的方式是通過將放入數據的操作置入後台來執行兩個操作（將數據放入管道，而在另外一段讀取它）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;Can you read this?&quot; &gt; mypipe &amp;</span></span>
<span class="line"><span>[1] 79302</span></span>
<span class="line"><span>$ cat mypipe</span></span>
<span class="line"><span>Can you read this?</span></span>
<span class="line"><span>[1]+ Done echo &quot;Can you read this?&quot; &gt; mypipe</span></span></code></pre></div><p>一旦管道被讀取或“耗幹”，該管道就清空了，儘管我們還能看見它並再次使用。可為什麼要費此周折呢？</p><h3 id="為何要使用命名管道" tabindex="-1">為何要使用命名管道？ <a class="header-anchor" href="#為何要使用命名管道" aria-label="Permalink to “為何要使用命名管道？”">​</a></h3><p>命名管道很少被使用的理由似乎很充分。畢竟在 Unix 系統上，總有多種不同的方式完成同樣的操作。有多種方式寫文件、讀文件、清空文件，儘管命名管道比它們來得更高效。</p><p>值得注意的是，命名管道的內容駐留在內存中而不是被寫到硬盤上。數據內容只有在輸入輸出端都打開時才會傳送。用户可以在管道的輸出端打開之前向管道多次寫入。通過使用命名管道，用户可以創建一個進程寫入管道並且另外一個進程讀取管道的流程，而不用關心協調二者時間上的同步。</p><p>用户可以創建一個單純等待數據出現在管道輸出端的進程，並在拿到輸出數據後對其進行操作。下列命令我們採用 <code>tail</code> 來等待數據出現。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tail -f mypipe</span></span></code></pre></div><p>一旦供給管道數據的進程結束了，我們就可以看到一些輸出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tail -f mypipe</span></span>
<span class="line"><span>Uranus replicated to WCDC7</span></span>
<span class="line"><span>Saturn replicated to WCDC8</span></span>
<span class="line"><span>Pluto replicated to WCDC9</span></span>
<span class="line"><span>Server replication operation completed</span></span></code></pre></div><p>如果研究一下向命名管道寫入的進程，用户也許會驚訝於它的資源消耗之少。在下面的 <code>ps</code> 命令輸出中，唯一顯著的資源消耗是虛擬內存（VSZ 那一列）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ps u -P 80038</span></span>
<span class="line"><span>USER PID %CPU %MEM VSZ RSS TTY STAT START TIME COMMAND</span></span>
<span class="line"><span>shs 80038 0.0 0.0 108488 764 pts/4 S 15:25 0:00 -bash</span></span></code></pre></div><p>命名管道與 Unix/Linux 系統上更常用的管道相比足以不同到擁有另一個名號，但是“管道”確實能反映出它們如何在進程間傳送數據的形象，故將稱其為“命名管道”還真是恰如其分。也許您在執行操作時就能從這個聰明的 Unix/Linux 特性中獲益匪淺呢。</p><hr>`,31)),t("p",null,[s[1]||(s[1]=a("via: ",-1)),e(i,{href:"https://www.networkworld.com/article/3251853/linux/why-use-named-pipes-on-linux.html"},{default:n(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3251853/linux/why-use-named-pipes-on-linux.html",-1)])]),_:1})]),t("p",null,[s[5]||(s[5]=a("作者：",-1)),e(i,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:n(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[6]||(s[6]=a(" 譯者：",-1)),e(i,{href:"https://github.com/YPBlib"},{default:n(()=>[...s[3]||(s[3]=[a("YPBlib",-1)])]),_:1}),s[7]||(s[7]=a(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[4]||(s[4]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=a("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[8]||(s[8]=[a("LCTT",-1)])]),_:1}),s[11]||(s[11]=a(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:n(()=>[...s[9]||(s[9]=[a("Linux中國",-1)])]),_:1}),s[12]||(s[12]=a(" 榮譽推出",-1))])])}const C=p(h,[["render",u]]);export{x as __pageData,C as default};
